#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool leap(ll year) {
    return year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll year;
    cin >> year;

    const bool originalLeap = leap(year);
    int offset = 0;

    for (ll next = year + 1;; ++next) {
        offset = (offset + (leap(next - 1) ? 2 : 1)) % 7;
        if (offset == 0 && leap(next) == originalLeap) {
            cout << next << '\n';
            break;
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool leap(ll year) {
    return year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll year;
    cin >> year;

    ll nextYear = year;
    int shift = 0;

    do {
        shift = (shift + (leap(nextYear) ? 2 : 1)) % 7;
        ++nextYear;
    } while (shift != 0 || leap(nextYear) != leap(year));

    cout << nextYear << '\n';
    return 0;
}

